insert into public.learning_packs(id,version,subject,title,scope,spec) values('science-density','1.0.0','과학','질량만으로 뜨고 가라앉음을 알 수 있을까?','물질의 밀도 비교. 균질한 물체, 물의 밀도 1 g/cm³. 표면장력·흡수·공기주머니를 무시한 이상화 모형. 공식 교육과정 적합성은 교사가 별도로 확인한다.','{"prompt": "물에 나무 80g(100cm³)과 철 20g(약 2.56cm³)을 넣습니다. 결과를 예상하고 근거를 쓰세요.", "choices": ["나무는 뜨고 철은 가라앉아요", "나무는 가라앉고 철은 떠요", "둘 다 떠요", "아직 모르겠다"], "activities": [{"id": "density-compare", "kind": "density", "title": "물체와 액체의 밀도 비교", "instruction": "질량·부피를 바꿔 두 물체의 밀도를 비교하세요. 질량만 같은 경우와 밀도가 같은 경우의 차이를 관찰하고 처음 설명을 고쳐 보세요."}], "transfer": {"prompt": "물에 A(60g,100cm³)와 B(30g,10cm³)를 넣으면 어떻게 되나요?", "choices": ["A는 뜨고 B는 가라앉아요", "A는 가라앉고 B는 떠요", "둘 다 떠요", "아직 모르겠다"]}, "rubric": ["조건·문맥을 구분함", "제시된 근거를 연결함", "자신의 설명을 명확히 표현함"]}'::jsonb);
insert into private.learning_keys(pack_id,pack_version,answer,transfer_answer,rubric) values('science-density','1.0.0','나무는 뜨고 철은 가라앉아요','A는 뜨고 B는 가라앉아요','["조건·문맥을 구분함", "제시된 근거를 연결함", "자신의 설명을 명확히 표현함"]'::jsonb);
insert into public.learning_packs(id,version,subject,title,scope,spec) values('math-fractions','1.0.0','수학','분모가 클수록 분수도 클까?','같은 전체를 같은 크기로 나눈 양과 양의 분수 비교. 분자와 분모는 자연수, 분모는 0이 아니다. 공식 교육과정 적합성은 교사가 별도로 확인한다.','{"prompt": "같은 크기의 피자를 나누었습니다. 1/3과 1/5 중 어느 양이 더 큰가요? 그림이나 분할의 의미로 설명해 보세요.", "choices": ["1/3이 더 커요", "1/5이 더 커요", "두 양은 같아요", "아직 모르겠다"], "activities": [{"id": "fraction-line", "kind": "number_line", "title": "같은 전체를 나눈 양 비교", "instruction": "두 막대의 전체 길이가 같음을 먼저 확인하세요. 분모를 바꾸어 한 조각이 차지하는 양을 관찰하고 처음 설명을 수정하세요."}], "transfer": {"prompt": "같은 전체에서 2/3과 2/5 중 어느 양이 더 큰가요? 근거도 적어 보세요.", "choices": ["2/3이 더 커요", "2/5이 더 커요", "두 양은 같아요", "아직 모르겠다"]}, "rubric": ["조건·문맥을 구분함", "제시된 근거를 연결함", "자신의 설명을 명확히 표현함"]}'::jsonb);
insert into private.learning_keys(pack_id,pack_version,answer,transfer_answer,rubric) values('math-fractions','1.0.0','1/3이 더 커요','2/3이 더 커요','["조건·문맥을 구분함", "제시된 근거를 연결함", "자신의 설명을 명확히 표현함"]'::jsonb);
insert into public.learning_packs(id,version,subject,title,scope,spec) values('reading-evidence','1.0.0','독해','주장을 뒷받침하는 근거 찾기','제공된 글 안에서 주장과 근거의 대응을 확인한다. 한정된 설문을 모든 학생의 생각으로 일반화하지 않는다. 창작된 예문이며 공식 교육과정 적합성은 교사가 별도로 확인한다.','{"prompt": "글: “우리 학교 도서관 운영 시간을 늘리자. 방과 후 도서관을 이용하는 학생 40명에게 물었더니 30명이 더 오래 이용하고 싶다고 답했다.” 이 글이 제안하는 것은 무엇인가요?", "choices": ["도서관 운영 시간을 늘리기", "모든 학생이 독서를 싫어한다는 결론", "도서관을 폐쇄하기", "아직 모르겠다"], "activities": [{"id": "evidence-compare", "kind": "evidence_comparison", "title": "문장과 근거를 나란히 비교", "instruction": "“응답 학생 40명 중 30명”이라는 근거와 “모든 학생”이라는 주장을 비교하세요. 글에서 말한 것과 말하지 않은 것을 구분해 처음 설명을 수정하세요."}], "transfer": {"prompt": "“설문에 참여한 학생 50명 중 35명이 운동장에 그늘이 필요하다고 답했다.” 이 문장이 직접 뒷받침하는 것은 무엇인가요?", "choices": ["응답한 학생 중 35명이 그늘을 원한다", "학교의 모든 학생이 그늘을 원한다", "어떤 학생도 그늘을 원하지 않는다", "아직 모르겠다"]}, "rubric": ["조건·문맥을 구분함", "제시된 근거를 연결함", "자신의 설명을 명확히 표현함"]}'::jsonb);
insert into private.learning_keys(pack_id,pack_version,answer,transfer_answer,rubric) values('reading-evidence','1.0.0','도서관 운영 시간을 늘리기','응답한 학생 중 35명이 그늘을 원한다','["조건·문맥을 구분함", "제시된 근거를 연결함", "자신의 설명을 명확히 표현함"]'::jsonb);
